import{_ as d,o as r,c as e,a3 as o}from"./chunks/framework.Cc-oPviL.js";const q=JSON.parse('{"title":"第十一章　二十条常见易错点","description":"","frontmatter":{},"headers":[],"relativePath":"timeseries/11.md","filePath":"timeseries/11.md"}'),a={name:"timeseries/11.md"};function s(n,t,i,u,_,l){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="第十一章-二十条常见易错点" tabindex="-1">第十一章　二十条常见易错点 <a class="header-anchor" href="#第十一章-二十条常见易错点" aria-label="Permalink to &quot;第十一章　二十条常见易错点&quot;">​</a></h1><p>以下二十条不是计算错误，而是方法误用——它们往往让结果看起来更好，因此更危险。每条后面都注明了错在哪。<br> 每一条都是实际作业与论文中反复出现的问题。&quot;错在哪&quot;一栏说明为什么它是错的。</p><table tabindex="0"><thead><tr><th>序号</th><th>错误做法</th><th>错在哪</th></tr></thead><tbody><tr><td>1</td><td>用全样本均值/标准差做标准化</td><td>测试期信息进入训练，属于信息泄漏</td></tr><tr><td>2</td><td>随机打乱时间顺序划分训练/测试集</td><td>破坏了时间依赖，评价结果完全无效</td></tr><tr><td>3</td><td>在测试集上反复比较模型</td><td>测试集被&quot;用旧&quot;，不再独立</td></tr><tr><td>4</td><td>比较不同 d 的模型的 AIC</td><td>似然基于不同数据变换，不可比</td></tr><tr><td>5</td><td>比较不同样本量的模型的 AIC</td><td>−2lnL 的量级随 n 变化，不可比</td></tr><tr><td>6</td><td>Ljung-Box 自由度不扣参数</td><td>自由度偏大 → p 值偏大 → 漏判不充分模型</td></tr><tr><td>7</td><td>扣参数时忘了常数项/漂移项</td><td>同上，这是最常见的具体错误</td></tr><tr><td>8</td><td>把&quot;不拒绝单位根&quot;说成&quot;证明有单位根&quot;</td><td>不拒绝只是证据不足，不是接受</td></tr><tr><td>9</td><td>ADF 只跑一种设定就下结论</td><td>结论对确定项设定高度敏感，须报告多种</td></tr><tr><td>10</td><td>对趋势平稳序列做差分</td><td>过度差分，引入不可逆 MA 根，放大方差</td></tr><tr><td>11</td><td>用样本内拟合优度当预测能力</td><td>过拟合模型的样本内 R² 可以很高但预测很差</td></tr><tr><td>12</td><td>对接近 0 的序列用 MAPE</td><td>分母趋零导致指标爆炸，且惩罚不对称</td></tr><tr><td>13</td><td>只报点预测不报区间</td><td>无法判断预测的不确定性，也无法评价区间质量</td></tr><tr><td>14</td><td>不做基准对比就宣称模型有效</td><td>没有参照，&quot;RMSE = 3.5&quot;没有意义</td></tr><tr><td>15</td><td>把滚动一步与固定原点的误差混算</td><td>两种实验设计，混算结果无法解释</td></tr><tr><td>16</td><td>残差非正态仍用正态区间</td><td>区间覆盖率偏离名义值，通常过窄</td></tr><tr><td>17</td><td>检出 ARCH 效应仍用常方差模型</td><td>标准误低估，区间在波动期失真</td></tr><tr><td>18</td><td>参数不显著就直接删</td><td>忽略了选模规则的前置性与长期预测的影响</td></tr><tr><td>19</td><td>根接近单位圆（如 1.0000002）仍判为可逆</td><td>数学上在圆外，统计上等同不可逆，预测极不稳定</td></tr><tr><td>20</td><td>NNAR 不设种子、不报告种子</td><td>结果不可复现，换台机器数值就变</td></tr></tbody></table><p>★ <strong>这 20 条的共同点</strong>：它们都不是&quot;算错了&quot;，而是&quot;用错了&quot;。计算错误容易发现，方法误用却会让整份分析在逻辑上失效——而且结果往往看起来更漂亮（R² 更高、误差更小），因此更危险。</p>',4)])])}const c=d(a,[["render",s]]);export{q as __pageData,c as default};
